from typing import Literal
from fastapi import FastAPI, HTTPException, status
from pydantic import BaseModel, Field, StrictInt

PlanType = Literal["basic", "plus", "max"]
QuotaStatus = Literal["ok", "warning", "exhausted"]

PLAN_QUOTAS: dict[PlanType, int] = {
    "basic": 5000,
    "plus": 20000,
    "max": 100000,
}


@dataclass
class SubscriberRecord:
    subscriber_ref: str
    plan: PlanType
    quota_mb: int
    used_mb: int = 0


subscribers: dict[str, SubscriberRecord] = {}


class SubscriberCreateRequest(BaseModel):
    subscriber_ref: str = Field(pattern=r"^S\d{8}\Z")
    plan: PlanType


class SubscriberCreateResponse(BaseModel):
    subscriber_ref: str
    plan: PlanType
    quota_mb: int


class UsageRequest(BaseModel):
    megabytes: StrictInt = Field(ge=1, le=100000)


class UsageResponse(BaseModel):
    used_mb: int
    remaining_mb: int
    status: QuotaStatus


class QuotaResponse(BaseModel):
    plan: PlanType
    quota_mb: int
    used_mb: int
    remaining_mb: int
    status: QuotaStatus


def compute_quota_state(used_mb: int, quota_mb: int) -> tuple[int, QuotaStatus]:
    remaining_mb = max(0, quota_mb - used_mb)
    if used_mb * 100 < quota_mb * 80:
        quota_status: QuotaStatus = "ok"
    elif used_mb <= quota_mb:
        quota_status = "warning"
    else:
        quota_status = "exhausted"
    return remaining_mb, quota_status


def get_subscriber_or_404(ref: str) -> SubscriberRecord:
    record = subscribers.get(ref)
    if record is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Subscriber not found",
        )
    return record


app = FastAPI()


@app.post(
    "/subscribers",
    response_model=SubscriberCreateResponse,
    status_code=status.HTTP_201_CREATED,
)
def create_subscriber(payload: SubscriberCreateRequest) -> SubscriberCreateResponse:
    if payload.subscriber_ref in subscribers:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Subscriber already exists",
        )
    quota_mb = PLAN_QUOTAS[payload.plan]
    record = SubscriberRecord(
        subscriber_ref=payload.subscriber_ref,
        plan=payload.plan,
        quota_mb=quota_mb,
        used_mb=0,
    )
    subscribers[payload.subscriber_ref] = record
    return SubscriberCreateResponse(
        subscriber_ref=record.subscriber_ref,
        plan=record.plan,
        quota_mb=record.quota_mb,
    )


@app.post(
    "/subscribers/{ref}/usage",
    response_model=UsageResponse,
    status_code=status.HTTP_200_OK,
)
def add_usage(ref: str, payload: UsageRequest) -> UsageResponse:
    record = get_subscriber_or_404(ref)
    record.used_mb += payload.megabytes
    remaining_mb, quota_status = compute_quota_state(record.used_mb, record.quota_mb)
    return UsageResponse(
        used_mb=record.used_mb,
        remaining_mb=remaining_mb,
        status=quota_status,
    )


@app.get(
    "/subscribers/{ref}/quota",
    response_model=QuotaResponse,
    status_code=status.HTTP_200_OK,
)
def get_quota(ref: str) -> QuotaResponse:
    record = get_subscriber_or_404(ref)
    remaining_mb, quota_status = compute_quota_state(record.used_mb, record.quota_mb)
    return QuotaResponse(
        plan=record.plan,
        quota_mb=record.quota_mb,
        used_mb=record.used_mb,
        remaining_mb=remaining_mb,
        status=quota_status,
    )


@app.post(
    "/subscribers/{ref}/reset",
    response_model=QuotaResponse,
    status_code=status.HTTP_200_OK,
)
def reset_usage(ref: str) -> QuotaResponse:
    record = get_subscriber_or_404(ref)
    record.used_mb = 0
    remaining_mb, quota_status = compute_quota_state(record.used_mb, record.quota_mb)
    return QuotaResponse(
        plan=record.plan,
        quota_mb=record.quota_mb,
        used_mb=record.used_mb,
        remaining_mb=remaining_mb,
        status=quota_status,
    )
